<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$min=post_int('min_id');$max=post_int('max_id');if(post('action')==='delete'){if($min>$max){flash('error','Invalid range.');}else{$pdo->prepare('DELETE FROM room WHERE room_id BETWEEN ? AND ?')->execute([$min,$max]);flash('success','Room range deleted.');}}redirect('rooms.php');}
$raw=$pdo->query('SELECT room_id,room_type FROM room ORDER BY room_id')->fetchAll();$groups=[];foreach($raw as $r){$n=count($groups);if($n===0||$groups[$n-1]['room_type']!==$r['room_type']||$groups[$n-1]['max_id']+1!=(int)$r['room_id'])$groups[]=['room_type'=>$r['room_type'],'min_id'=>(int)$r['room_id'],'max_id'=>(int)$r['room_id']];else$groups[$n-1]['max_id']=(int)$r['room_id'];}
page_header('Rooms','room');?>
<div class="page-head"><h1>Rooms</h1><a class="btn primary" href="room_form.php">Add Rooms</a></div><section class="card table-wrap"><table><thead><tr><th>Room Type</th><th>Min ID</th><th>Max ID</th><th>Quantity</th><th>Actions</th></tr></thead><tbody><?php foreach($groups as $g):?><tr><td><?=e($g['room_type'])?></td><td><?=$g['min_id']?></td><td><?=$g['max_id']?></td><td><?=$g['max_id']-$g['min_id']+1?></td><td class="actions"><a href="room_form.php?type=<?=urlencode($g['room_type'])?>&min=<?=$g['min_id']?>&max=<?=$g['max_id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this room range?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="min_id" value="<?=$g['min_id']?>"><input type="hidden" name="max_id" value="<?=$g['max_id']?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$groups):?><tr><td colspan="5" class="empty">No rooms configured.</td></tr><?php endif;?></tbody></table></section><?php page_footer();?>
